1	import {createChatOrchestrator} from './chatOrchestrator.js';
2	import type {OrchestratorHooks} from './chatOrchestrator.js';
3	import type {AIProvider, MessageChunk, SendMessageParams, UsageMetadata} from '../types/ai.js';
4	import {AIError} from '../types/ai.js';
5	import type {ChatSession} from '../types/session.js';
6	import {PromptBuilder} from '../infrastructure/builders/promptBuilder.js';
7	import {ToolRegistry} from './tools/registry.js';
8	import type {ToolResponse} from './tools/registry.js';
9	import type {OutgoingMessage} from '../types/messages.js';
10	import type {SessionEntry} from '../types/session.js';
11	
12	// Fixed: nothing asserts on it, and new Date() would tie the run to the clock.
13	const SENT_AT = '2026-01-01T00:00:00.000Z';
14	
15	// One expect per test needs the rejection as a value rather than a matcher.
16	const outcomeOf = (call: Promise<unknown>): Promise<string> =>
17	  call.then(() => 'resolved without throwing').catch((error: Error) => error.message);
18	
19	function createSession(content: string): ChatSession {
20	  return {
21	    sessionId: 's1',
22	    userId: 'u1',
23	    entries: [{role: 'user', content, timestamp: SENT_AT}],
24	  };
25	}
26	
27	function createMockProvider(response: string, usage?: UsageMetadata): AIProvider {
28	  return {
29	    async *sendMessage(_params: SendMessageParams): AsyncGenerator<MessageChunk> {
30	      yield {type: 'text', text: response};
31	      yield {type: 'stop', stopReason: 'end_turn', usage};
32	    },
33	    async generateStructured<T>(): Promise<T> {
34	      return {} as T;
35	    },
36	  };
37	}
38	
39	function createErrorProvider(error: Error): AIProvider {
40	  return {
41	    // eslint-disable-next-line require-yield
42	    async *sendMessage(): AsyncGenerator<MessageChunk> {
43	      throw error;
44	    },
45	    async generateStructured<T>(): Promise<T> {
46	      return {} as T;
47	    },
48	  };
49	}
50	
51	const promptBuilder = new PromptBuilder({identity: 'You are a test assistant.'});
52	
53	type RecordedHook =
54	  | 'beforeSession'
55	  | 'beforeUserInput'
56	  | 'afterUserInput'
57	  | 'beforeModelResponse'
58	  | 'afterModelResponse'
59	  | 'afterSession'
60	  | 'onError';
61	
62	// Only the named hooks are installed: one that merely exists changes the observed order.
63	const recordingHooks = (callOrder: string[], names: RecordedHook[]): OrchestratorHooks => {
64	  const all: Required<OrchestratorHooks> = {
65	    beforeSession: async () => void callOrder.push('beforeSession'),
66	    beforeUserInput: async (_session, msg) => {
67	      callOrder.push('beforeUserInput');
68	      return msg;
69	    },
70	    afterUserInput: async () => void callOrder.push('afterUserInput'),
71	    beforeModelResponse: async (_session, systemPrompt) => {
72	      callOrder.push('beforeModelResponse');
73	      return systemPrompt;
74	    },
75	    afterModelResponse: async () => void callOrder.push('afterModelResponse'),
76	    afterSession: async () => void callOrder.push('afterSession'),
77	    onError: async () => void callOrder.push('onError'),
78	  };
79	
80	  return Object.fromEntries(names.map(name => [name, all[name]])) as OrchestratorHooks;
81	};
82	
83	// Records what the orchestrator actually sent, for tests that assert on the request.
84	const capturingProvider = (): {provider: AIProvider; sent: {systemPrompt: string; lastUserContent: string}} => {
85	  const sent = {systemPrompt: '', lastUserContent: ''};
86	
87	  return {
88	    sent,
89	    provider: {
90	      async *sendMessage(params: SendMessageParams): AsyncGenerator<MessageChunk> {
91	        sent.systemPrompt = params.systemPrompt;
92	        const last = params.messages[params.messages.length - 1];
93	        sent.lastUserContent = typeof last.content === 'string' ? last.content : '';
94	        yield {type: 'text', text: 'ok'};
95	        yield {type: 'stop', stopReason: 'end_turn'};
96	      },
97	      async generateStructured<T>(): Promise<T> {
98	        return {} as T;
99	      },
100	    },
101	  };
102	};
103	
104	describe('ChatOrchestrator hooks', () => {
105	  describe('beforeSession', () => {
106	    it('called before anything else', async () => {
107	      const callOrder: string[] = [];
108	      const hooks = recordingHooks(callOrder, ['beforeSession', 'beforeUserInput', 'beforeModelResponse']);
109	
110	      const orchestrator = createChatOrchestrator(createMockProvider('hi'), promptBuilder, undefined, {hooks});
111	      await orchestrator.processMessage(createSession('hello'));
112	
113	      expect(callOrder[0]).toBe('beforeSession');
114	    });
115	  });
116	
117	  describe('afterSession', () => {
118	    it('called after everything completes', async () => {
119	      const callOrder: string[] = [];
120	      const hooks = recordingHooks(callOrder, ['afterModelResponse', 'afterSession']);
121	
122	      const orchestrator = createChatOrchestrator(createMockProvider('hi'), promptBuilder, undefined, {hooks});
123	      await orchestrator.processMessage(createSession('hello'));
124	
125	      expect(callOrder).toEqual(['afterModelResponse', 'afterSession']);
126	    });
127	
128	    it('called even when an error occurs', async () => {
129	      let afterSessionCalled = false;
130	      const hooks: OrchestratorHooks = {
131	        onError: async () => {},
132	        afterSession: async () => {
133	          afterSessionCalled = true;
134	        },
135	      };
136	
137	      const orchestrator = createChatOrchestrator(createErrorProvider(new Error('boom')), promptBuilder, undefined, {
138	        hooks,
139	      });
140	      const outcome = await outcomeOf(orchestrator.processMessage(createSession('hello')));
141	
142	      expect({outcome, afterSessionCalled}).toEqual({outcome: 'boom', afterSessionCalled: true});
143	    });
144	  });
145	
146	  describe('beforeUserInput', () => {
147	    it('receives the last user message content', async () => {
148	      let receivedMessage = '';
149	      const hooks: OrchestratorHooks = {
150	        beforeUserInput: async (_session, userMessage) => {
151	          receivedMessage = userMessage;
152	          return userMessage;
153	        },
154	      };
155	
156	      const orchestrator = createChatOrchestrator(createMockProvider('ok'), promptBuilder, undefined, {hooks});
157	      await orchestrator.processMessage(createSession('my answer'));
158	
159	      expect(receivedMessage).toBe('my answer');
160	    });
161	
162	    it('modifies user message when returning different value', async () => {
163	      const {provider, sent} = capturingProvider();
164	
165	      const hooks: OrchestratorHooks = {
166	        beforeUserInput: async (_session, _msg) => 'sanitized input',
167	      };
168	
169	      const orchestrator = createChatOrchestrator(provider, promptBuilder, undefined, {hooks});
170	      await orchestrator.processMessage(createSession('raw input'));
171	
172	      expect(sent.lastUserContent).toBe('sanitized input');
173	    });
174	  });
175	
176	  describe('afterUserInput', () => {
177	    it('receives user message after any beforeUserInput modification', async () => {
178	      let afterReceived = '';
179	      const hooks: OrchestratorHooks = {
180	        beforeUserInput: async (_s, _msg) => 'modified',
181	        afterUserInput: async (_s, msg) => {
182	          afterReceived = msg;
183	        },
184	      };
185	
186	      const orchestrator = createChatOrchestrator(createMockProvider('ok'), promptBuilder, undefined, {hooks});
187	      await orchestrator.processMessage(createSession('original'));
188	
189	      expect(afterReceived).toBe('modified');
190	    });
191	  });
192	
193	  describe('beforeModelResponse', () => {
194	    it('replaces system prompt with returned value', async () => {
195	      const {provider, sent} = capturingProvider();
196	
197	      const hooks: OrchestratorHooks = {
198	        beforeModelResponse: async (_session, _basePrompt) => 'Custom prompt for this question',
199	      };
200	
201	      const orchestrator = createChatOrchestrator(provider, promptBuilder, undefined, {hooks});
202	      await orchestrator.processMessage(createSession('hello'));
203	
204	      expect(sent.systemPrompt).toBe('Custom prompt for this question');
205	    });
206	  });
207	
208	  describe('afterModelResponse', () => {
209	    it('receives collected response text and usage', async () => {
210	      const usage: UsageMetadata = {inputTokens: 10, outputTokens: 5, totalTokens: 15};
211	      let receivedText = '';
212	      let receivedUsage: UsageMetadata | undefined;
213	
214	      const hooks: OrchestratorHooks = {
215	        afterModelResponse: async (_session, text, u) => {
216	          receivedText = text;
217	          receivedUsage = u;
218	        },
219	      };
220	
221	      const orchestrator = createChatOrchestrator(createMockProvider('hello world', usage), promptBuilder, undefined, {
222	        hooks,
223	      });
224	      await orchestrator.processMessage(createSession('hi'));
225	
226	      expect({receivedText, receivedUsage}).toEqual({receivedText: 'hello world', receivedUsage: usage});
227	    });
228	
229	    it('not called when stream throws', async () => {
230	      let afterCalled = false;
231	      const hooks: OrchestratorHooks = {
232	        afterModelResponse: async () => {
233	          afterCalled = true;
234	        },
235	        onError: async () => {},
236	      };
237	
238	      const orchestrator = createChatOrchestrator(
239	        createErrorProvider(new AIError('fail', 'TEST')),
240	        promptBuilder,
241	        undefined,
242	        {hooks}
243	      );
244	      const outcome = await outcomeOf(orchestrator.processMessage(createSession('hello')));
245	
246	      expect({outcome, afterCalled}).toEqual({outcome: 'fail', afterCalled: false});
247	    });
248	  });
249	
250	  describe('onError', () => {
251	    it('called with session and error when stream fails', async () => {
252	      let receivedError: Error | undefined;
253	      const hooks: OrchestratorHooks = {
254	        onError: async (_session, error) => {
255	          receivedError = error;
256	        },
257	      };
258	
259	      const orchestrator = createChatOrchestrator(
260	        createErrorProvider(new AIError('rate limited', 'RATE_LIMITED')),
261	        promptBuilder,
262	        undefined,
263	        {hooks}
264	      );
265	      const outcome = await outcomeOf(orchestrator.processMessage(createSession('hello')));
266	
267	      expect({outcome, receivedErrorMessage: receivedError?.message}).toEqual({
268	        outcome: 'rate limited',
269	        receivedErrorMessage: 'rate limited',
270	      });
271	    });
272	
273	    it('error still propagates after onError hook', async () => {
274	      const hooks: OrchestratorHooks = {
275	        onError: async () => {},
276	      };
277	
278	      const orchestrator = createChatOrchestrator(createErrorProvider(new Error('boom')), promptBuilder, undefined, {
279	        hooks,
280	      });
281	      await expect(orchestrator.processMessage(createSession('hello'))).rejects.toThrow('boom');
282	    });
283	  });
284	
285	  describe('full lifecycle order', () => {
286	    it('calls all hooks in correct order', async () => {
287	      const callOrder: string[] = [];
288	      const usage: UsageMetadata = {inputTokens: 5, outputTokens: 3, totalTokens: 8};
289	
290	      const hooks: OrchestratorHooks = {
291	        beforeSession: async () => {
292	          callOrder.push('beforeSession');
293	        },
294	        beforeUserInput: async (_s, msg) => {
295	          callOrder.push('beforeUserInput');
296	          return msg;
297	        },
298	        afterUserInput: async () => {
299	          callOrder.push('afterUserInput');
300	        },
301	        beforeModelResponse: async (_s, p) => {
302	          callOrder.push('beforeModelResponse');
303	          return p;
304	        },
305	        afterModelResponse: async () => {
306	          callOrder.push('afterModelResponse');
307	        },
308	        afterSession: async () => {
309	          callOrder.push('afterSession');
310	        },
311	      };
312	
313	      const orchestrator = createChatOrchestrator(createMockProvider('ok', usage), promptBuilder, undefined, {hooks});
314	      await orchestrator.processMessage(createSession('hello'));
315	
316	      expect(callOrder).toEqual([
317	        'beforeSession',
318	        'beforeUserInput',
319	        'afterUserInput',
320	        'beforeModelResponse',
321	        'afterModelResponse',
322	        'afterSession',
323	      ]);
324	    });
325	
326	    it('error path calls onError then afterSession', async () => {
327	      const callOrder: string[] = [];
328	
329	      const hooks = recordingHooks(callOrder, [
330	        'beforeSession',
331	        'beforeUserInput',
332	        'afterUserInput',
333	        'beforeModelResponse',
334	        'afterModelResponse',
335	        'onError',
336	        'afterSession',
337	      ]);
338	
339	      const orchestrator = createChatOrchestrator(createErrorProvider(new Error('fail')), promptBuilder, undefined, {
340	        hooks,
341	      });
342	      const outcome = await outcomeOf(orchestrator.processMessage(createSession('hello')));
