1	/**
2	 * callee-below-caller — place functions in the downward direction: a reader
3	 * meets the caller first and finds the callee below it. A file then reads like
4	 * a newspaper — headline at the top, detail as you scroll — instead of forcing
5	 * the reader to hold a pile of helpers in their head before the point arrives.
6	 *
7	 * What counts: only top-level `FunctionDeclaration`s (direct `Program` children,
8	 * including `export function`). For each, the FIRST reference in source order
9	 * that lives inside another top-level function names its caller; a callee whose
10	 * declaration sits ABOVE that caller is reported. Exemptions:
11	 *   - a callee referenced at module level (exports, top-level statements,
12	 *     class bodies) is an entry point, not a helper, and is never reported;
13	 *   - mutual recursion (A calls B and B calls A) has no downward order;
14	 *   - a callee with several callers is judged against its first caller only;
15	 *   - with `exportedFirst` (default true) exported functions are never
16	 *     reported — they are the entry points and belong at the top.
17	 *
18	 * Detect-only: moving a declaration is a cut-and-paste a human should own.
19	 */
20	function declaredFunction(statement) {
21	    const declaration = statement.type === "ExportNamedDeclaration" ||
22	        statement.type === "ExportDefaultDeclaration"
23	        ? statement.declaration
24	        : statement;
25	    if (!declaration || declaration.type !== "FunctionDeclaration") {
